import java.util.*;

class Solution {
    private static final int LIMIT = 1_000_000;
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public boolean isEscapePossible(int[][] blocked, int[] source, int[] target) {
        Set<Long> blockedSet = new HashSet<>();
        for (int[] cell : blocked) {
            blockedSet.add(encode(cell[0], cell[1]));
        }
        int maxEnclosed = blocked.length * (blocked.length - 1) / 2;
        return canReachOrEscape(blockedSet, source, target, maxEnclosed)
                && canReachOrEscape(blockedSet, target, source, maxEnclosed);
    }

    private boolean canReachOrEscape(Set<Long> blockedSet, int[] start, int[] finish, int maxEnclosed) {
        if (maxEnclosed == 0) {
            return true;
        }
        Set<Long> seen = new HashSet<>();
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{start[0], start[1]});
        seen.add(encode(start[0], start[1]));

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            if (cell[0] == finish[0] && cell[1] == finish[1]) {
                return true;
            }
            if (seen.size() > maxEnclosed) {
                return true;
            }
            for (int[] dir : DIRS) {
                int nr = cell[0] + dir[0];
                int nc = cell[1] + dir[1];
                long key = encode(nr, nc);
                if (0 <= nr && nr < LIMIT && 0 <= nc && nc < LIMIT
                        && !blockedSet.contains(key) && seen.add(key)) {
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return false;
    }

    private long encode(int row, int col) {
        return (long) row * LIMIT + col;
    }
}

