class Solution {
    private static final int LIMIT = 1_000_000;
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public boolean isEscapePossible(int[][] blocked, int[] source, int[] target) {
        Set<Long> blockedSet = new HashSet<>();
        for (int[] cell : blocked) {
            blockedSet.add(encode(cell[0], cell[1]));
        }
        int maxEnclosed = blocked.length * (blocked.length - 1) / 2;
        return canConnectOrMutuallyEscape(blockedSet, source, target, maxEnclosed);
    }

    private boolean canConnectOrMutuallyEscape(Set<Long> blockedSet, int[] source, int[] target, int maxEnclosed) {
        if (maxEnclosed == 0) {
            return true;
        }
        ArrayDeque<int[]> fromSource = new ArrayDeque<>();
        ArrayDeque<int[]> fromTarget = new ArrayDeque<>();
        Set<Long> seenFromSource = new HashSet<>();
        Set<Long> seenFromTarget = new HashSet<>();
        addStart(fromSource, seenFromSource, source);
        addStart(fromTarget, seenFromTarget, target);

        boolean sourceEscaped = false;
        boolean targetEscaped = false;
        while (!fromSource.isEmpty() || !fromTarget.isEmpty()) {
            if (!sourceEscaped && expandOneLayer(fromSource, seenFromSource, seenFromTarget, blockedSet)) {
                return true;
            }
            if (seenFromSource.size() > maxEnclosed) {
                sourceEscaped = true;
            }

            if (!targetEscaped && expandOneLayer(fromTarget, seenFromTarget, seenFromSource, blockedSet)) {
                return true;
            }
            if (seenFromTarget.size() > maxEnclosed) {
                targetEscaped = true;
            }

            if (sourceEscaped && targetEscaped) {
                return true;
            }
            if ((!sourceEscaped && fromSource.isEmpty()) || (!targetEscaped && fromTarget.isEmpty())) {
                return false;
            }
        }
        return sourceEscaped && targetEscaped;
    }

    private void addStart(ArrayDeque<int[]> frontier, Set<Long> seen, int[] cell) {
        frontier.offer(new int[]{cell[0], cell[1]});
        seen.add(encode(cell[0], cell[1]));
    }

    private boolean expandOneLayer(ArrayDeque<int[]> frontier, Set<Long> ownSeen,
                                   Set<Long> otherSeen, Set<Long> blockedSet) {
        int layerSize = frontier.size();
        for (int i = 0; i < layerSize; i++) {
            int[] cell = frontier.poll();
            for (int[] dir : DIRS) {
                int nr = cell[0] + dir[0];
                int nc = cell[1] + dir[1];
                long key = encode(nr, nc);
                if (0 <= nr && nr < LIMIT && 0 <= nc && nc < LIMIT
                        && !blockedSet.contains(key) && ownSeen.add(key)) {
                    if (otherSeen.contains(key)) {
                        return true;
                    }
                    frontier.offer(new int[]{nr, nc});
                }
            }
        }
        return false;
    }

    private long encode(int row, int col) {
        return (long) row * LIMIT + col;
    }
}

