class Solution {
    private static final int LIMIT = 1_000_000;
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public boolean isEscapePossible(int[][] blocked, int[] source, int[] target) {
        Set<Integer> xs = new HashSet<>();
        Set<Integer> ys = new HashSet<>();
        addPoint(xs, ys, source);
        addPoint(xs, ys, target);
        for (int[] cell : blocked) {
            addPoint(xs, ys, cell);
        }

        List<Integer> xValues = sorted(xs);
        List<Integer> yValues = sorted(ys);
        Map<Integer, Integer> xIndex = indexMap(xValues);
        Map<Integer, Integer> yIndex = indexMap(yValues);

        boolean[][] blockedGrid = new boolean[xValues.size()][yValues.size()];
        for (int[] cell : blocked) {
            blockedGrid[xIndex.get(cell[0])][yIndex.get(cell[1])] = true;
        }

        return bfs(blockedGrid,
                xIndex.get(source[0]), yIndex.get(source[1]),
                xIndex.get(target[0]), yIndex.get(target[1]));
    }

    private boolean bfs(boolean[][] blockedGrid, int sx, int sy, int tx, int ty) {
        int rows = blockedGrid.length;
        int cols = blockedGrid[0].length;
        boolean[][] seen = new boolean[rows][cols];
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{sx, sy});
        seen[sx][sy] = true;

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            if (cell[0] == tx && cell[1] == ty) {
                return true;
            }
            for (int[] dir : DIRS) {
                int nr = cell[0] + dir[0];
                int nc = cell[1] + dir[1];
                if (0 <= nr && nr < rows && 0 <= nc && nc < cols
                        && !seen[nr][nc] && !blockedGrid[nr][nc]) {
                    seen[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return false;
    }

    private void addPoint(Set<Integer> xs, Set<Integer> ys, int[] point) {
        addAround(xs, point[0]);
        addAround(ys, point[1]);
    }

    private void addAround(Set<Integer> values, int value) {
        for (int delta = -1; delta <= 1; delta++) {
            int next = value + delta;
            if (0 <= next && next < LIMIT) {
                values.add(next);
            }
        }
    }

    private List<Integer> sorted(Set<Integer> values) {
        List<Integer> list = new ArrayList<>(values);
        Collections.sort(list);
        return list;
    }

    private Map<Integer, Integer> indexMap(List<Integer> values) {
        Map<Integer, Integer> index = new HashMap<>();
        for (int i = 0; i < values.size(); i++) {
            index.put(values.get(i), i);
        }
        return index;
    }
}

import java.util.*;

class Solution {
    private static final int LIMIT = 1_000_000;
    private static final int[][] DIRS = {{1, 0}, {0, 1}};

    public boolean isEscapePossible(int[][] blocked, int[] source, int[] target) {
        Set<Integer> xs = new HashSet<>();
        Set<Integer> ys = new HashSet<>();
        addPoint(xs, ys, source);
        addPoint(xs, ys, target);
        for (int[] cell : blocked) {
            addPoint(xs, ys, cell);
        }

        List<Integer> xValues = sorted(xs);
        List<Integer> yValues = sorted(ys);
        Map<Integer, Integer> xIndex = indexMap(xValues);
        Map<Integer, Integer> yIndex = indexMap(yValues);
        int rows = xValues.size();
        int cols = yValues.size();

        boolean[][] blockedGrid = new boolean[rows][cols];
        for (int[] cell : blocked) {
            blockedGrid[xIndex.get(cell[0])][yIndex.get(cell[1])] = true;
        }

        DSU dsu = new DSU(rows * cols);
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (blockedGrid[row][col]) {
                    continue;
                }
                for (int[] dir : DIRS) {
                    int nextRow = row + dir[0];
                    int nextCol = col + dir[1];
                    if (nextRow < rows && nextCol < cols && !blockedGrid[nextRow][nextCol]) {
                        dsu.union(id(row, col, cols), id(nextRow, nextCol, cols));
                    }
                }
            }
        }

        int sourceId = id(xIndex.get(source[0]), yIndex.get(source[1]), cols);
        int targetId = id(xIndex.get(target[0]), yIndex.get(target[1]), cols);
        return dsu.find(sourceId) == dsu.find(targetId);
    }

    private int id(int row, int col, int cols) {
        return row * cols + col;
    }

    private void addPoint(Set<Integer> xs, Set<Integer> ys, int[] point) {
        addAround(xs, point[0]);
        addAround(ys, point[1]);
    }

    private void addAround(Set<Integer> values, int value) {
        for (int delta = -1; delta <= 1; delta++) {
            int next = value + delta;
            if (0 <= next && next < LIMIT) {
                values.add(next);
            }
        }
    }

    private List<Integer> sorted(Set<Integer> values) {
        List<Integer> list = new ArrayList<>(values);
        Collections.sort(list);
        return list;
    }

    private Map<Integer, Integer> indexMap(List<Integer> values) {
        Map<Integer, Integer> index = new HashMap<>();
        for (int i = 0; i < values.size(); i++) {
            index.put(values.get(i), i);
        }
        return index;
    }

    private static final class DSU {
        private final int[] parent;
        private final int[] rank;

        DSU(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
        }

        int find(int value) {
            if (parent[value] != value) {
                parent[value] = find(parent[value]);
            }
            return parent[value];
        }

        void union(int left, int right) {
            int rootLeft = find(left);
            int rootRight = find(right);
            if (rootLeft == rootRight) {
                return;
            }
            if (rank[rootLeft] < rank[rootRight]) {
                parent[rootLeft] = rootRight;
            } else if (rank[rootLeft] > rank[rootRight]) {
                parent[rootRight] = rootLeft;
            } else {
                parent[rootRight] = rootLeft;
                rank[rootLeft]++;
            }
        }
    }
}

import java.util.*;

class Solution {
    private static final int LIMIT = 1_000_000;
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public boolean isEscapePossible(int[][] blocked, int[] source, int[] target) {
        Set<Long> blockedSet = new HashSet<>();
        for (int[] cell : blocked) {
            blockedSet.add(encode(cell[0], cell[1]));
        }
        int maxEnclosed = blocked.length * (blocked.length - 1) / 2;
        return astarEscapes(blockedSet, source, target, maxEnclosed)
                && astarEscapes(blockedSet, target, source, maxEnclosed);
    }

    private boolean astarEscapes(Set<Long> blockedSet, int[] start, int[] finish, int maxEnclosed) {
        if (maxEnclosed == 0) {
            return true;
        }
        PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(cell -> cell[2]));
        Set<Long> seen = new HashSet<>();
        heap.offer(new int[]{start[0], start[1], manhattan(start[0], start[1], finish)});
        seen.add(encode(start[0], start[1]));

        while (!heap.isEmpty()) {
            int[] cell = heap.poll();
            if (cell[0] == finish[0] && cell[1] == finish[1]) {
                return true;
            }
            if (seen.size() > maxEnclosed) {
                return true;
            }
            for (int[] dir : DIRS) {
                int nr = cell[0] + dir[0];
                int nc = cell[1] + dir[1];
                long key = encode(nr, nc);
                if (0 <= nr && nr < LIMIT && 0 <= nc && nc < LIMIT
                        && !blockedSet.contains(key) && seen.add(key)) {
                    heap.offer(new int[]{nr, nc, manhattan(nr, nc, finish)});
                }
            }
        }
        return false;
    }

    private int manhattan(int row, int col, int[] target) {
        return Math.abs(row - target[0]) + Math.abs(col - target[1]);
    }

    private long encode(int row, int col) {
        return (long) row * LIMIT + col;
    }
}
